// Generated by `just generate` from `src/plugins/claudetto/slices/prompt/adapters/mod.ts`. Edit the source and run `just generate`.
// The mod handlers of the `prompt` slice:
// `prompt.compose`, `agent.spawn`, and `session.append` for the prompt variant of the model,
// and `prompt.section`, which answers each built-in section that has a transform with its shorter text,
// and the `context_management` section with the text of the compaction state.

import type { PluginOptions } from "claude-code";
import type { Handler } from "../../../kernel/slice.ts";
import {
  composeSections,
  missLines,
  transformText,
  variantKey,
  withBlock,
} from "../domain/apply.ts";
import {
  CONTEXT_SECTION,
  type CompactionState,
  compactionState,
  gatedText,
} from "../domain/compaction.ts";
import type { VariantKey } from "../domain/variants.ts";
import { STATE_SECTIONS, TRANSFORMS } from "../transforms/index.ts";

// The variant key of each session, chosen at the first `prompt.compose` of the session and kept.
// A model switch changes nothing, because a changed system prompt breaks the cache.
const variants = new Map<string, VariantKey | null>();

/** The `userConfig` values of the plugin, which the generated `register` gives to `keepOptions`. */
const kept: { options: PluginOptions } = { options: {} };

/** Keeps the `userConfig` values of the plugin for the compaction gate. */
export const keepOptions = (options: PluginOptions): void => {
  kept.options = options;
};

/** The compaction state of the session. */
const stateOf = async ($: Parameters<Handler<"prompt.section">>[0]) =>
  compactionState(kept.options, await $.env.get("DISABLE_COMPACT"));

/**
 * The transformed text of a built-in section.
 * `prompt.section` logs one debug line for each anchor that finds nothing.
 * `prompt.compose` logs nothing, because the engine may give it a section that `prompt.section` changed already,
 * and the anchors of a changed section find nothing without a change in Claude Code.
 */
const transformed = (
  $: Parameters<Handler<"prompt.section">>[0],
  id: string,
  text: string,
  state: CompactionState,
  log: boolean,
): string => {
  if (log)
    for (const line of missLines(id, text)) $.ui.log(line, { to: "debug" });
  return transformText(id, text, state);
};

export const onCompose: Handler<"prompt.compose"> = async ($, e, next) => {
  const result = await next(e);
  if (e.traits.includes("bare")) return result;
  // The state is read only when a section needs it.
  const gated = result.sections.some(
    (s) => s.id === CONTEXT_SECTION || STATE_SECTIONS.has(s.id),
  );
  const state = gated ? await stateOf($) : "built-in";
  const sections = result.sections.map((s) => ({
    ...s,
    text:
      s.id === CONTEXT_SECTION
        ? gatedText(s.text, state)
        : transformed($, s.id, s.text, state, false),
  }));
  const session = await $.session.id();
  if (!variants.has(session))
    variants.set(session, variantKey(e.promptModel || e.model));
  const key = variants.get(session);
  return key
    ? { sections: composeSections(sections, key, $.plugin.root) }
    : { sections };
};

// A subagent gets its system prompt from its agent body, so its model block goes to the end of its task row.
// The call of `agent.spawn` has no model when the agent file or `CLAUDE_CODE_SUBAGENT_MODEL` chooses it,
// and only the result of `next(e)` has the model that the engine resolved.
// So the spawn passes its task prompt on unchanged and keeps a promise of the variant key for that prompt,
// and the `session.append` hook writes the block into the task row of the subagent.
type Pending = { key: VariantKey | null; agentId?: string | undefined };
const pending = new Map<string, Promise<Pending>>();

export const onSpawn: Handler<"agent.spawn"> = async (_$, e, next) => {
  let settle: (p: Pending) => void = () => {};
  pending.set(e.prompt, new Promise((resolve) => (settle = resolve)));
  try {
    const result = await next(e);
    const key = variantKey(result.model ?? null);
    settle({ key, agentId: result.agentId });
    if (!key) pending.delete(e.prompt);
    return result;
  } catch (err) {
    settle({ key: null });
    pending.delete(e.prompt);
    throw err;
  }
};

// The task row of a subagent is a user row of its loop with a text block that is the task prompt.
export const onAppend: Handler<"session.append"> = async (_$, e, next) => {
  if (!e.agentId || e.message.type !== "user") return next(e);
  const text = (b: { type: string; [field: string]: unknown }) =>
    b.type === "text" && typeof b["text"] === "string" ? b["text"] : null;
  const at = e.message.content.findIndex((b) => pending.has(text(b) ?? ""));
  const prompt = at < 0 ? null : text(e.message.content[at] ?? { type: "" });
  if (prompt === null) return next(e);
  const spawn = await pending.get(prompt);
  pending.delete(prompt);
  if (!spawn?.key || (spawn.agentId && spawn.agentId !== e.agentId))
    return next(e);
  const content = e.message.content.with(at, {
    ...e.message.content[at],
    type: "text",
    text: withBlock(prompt, spawn.key),
  });
  return next({ ...e, message: { ...e.message, content } });
};

// The transform of a section is the same for each call, so the cached answer keeps the prompt cache.
// The `context_management` section gets the text of the compaction state (`domain/compaction.ts`).
export const onSection: Handler<"prompt.section"> = async ($, e, next) => {
  if (e.text === null) return next(e);
  if (e.name === CONTEXT_SECTION) {
    const state = await stateOf($);
    return state === "built-in" ? next(e) : { text: gatedText(e.text, state) };
  }
  if (!TRANSFORMS.has(e.name)) return next(e);
  return {
    text: transformed(
      $,
      e.name,
      e.text,
      STATE_SECTIONS.has(e.name) ? await stateOf($) : "built-in",
      true,
    ),
  };
};
